import { useEffect, useRef, useState } from "react";

export function SearchBox({ search, debounceMs = 300, minChars = 2 }) {
  const [value, setValue] = useState("");
  const [editVersion, setEditVersion] = useState(0);
  const [results, setResults] = useState([]);
  const [status, setStatus] = useState("");
  const [hasError, setHasError] = useState(false);

  const mountedRef = useRef(true);
  const valueRef = useRef(value);
  const searchRef = useRef(search);
  const minCharsRef = useRef(minChars);
  const timerRef = useRef(null);
  const timerGenerationRef = useRef(0);
  const latestRequestRef = useRef(null);

  valueRef.current = value;
  searchRef.current = search;
  minCharsRef.current = minChars;

  function clearPendingTimer() {
    if (timerRef.current !== null) {
      clearTimeout(timerRef.current);
      timerRef.current = null;
    }
    timerGenerationRef.current += 1;
  }

  function resetForShortQuery() {
    clearPendingTimer();

    const request = latestRequestRef.current;
    latestRequestRef.current = null;

    if (
      request?.state === "pending" &&
      !request.controller.signal.aborted
    ) {
      request.controller.abort();
    }

    setResults([]);
    setHasError(false);
    setStatus("");
  }

  function startRequest(query) {
    clearPendingTimer();

    if (!mountedRef.current) {
      return;
    }

    const previousRequest = latestRequestRef.current;

    if (
      previousRequest?.query === query &&
      (previousRequest.state === "pending" ||
        previousRequest.state === "succeeded")
    ) {
      return;
    }

    const controller = new AbortController();
    const request = {
      query,
      controller,
      state: "pending",
    };

    latestRequestRef.current = request;

    if (
      previousRequest &&
      !previousRequest.controller.signal.aborted
    ) {
      previousRequest.controller.abort();
    }

    setHasError(false);
    setStatus("Searching...");

    const resolveRequest = (nextResults) => {
      if (
        !mountedRef.current ||
        latestRequestRef.current !== request ||
        controller.signal.aborted
      ) {
        return;
      }

      request.state = "succeeded";
      setResults(nextResults);
      setHasError(false);
      setStatus(nextResults.length === 0 ? "No results" : "");
    };

    const rejectRequest = (error) => {
      if (
        !mountedRef.current ||
        latestRequestRef.current !== request
      ) {
        return;
      }

      if (
        controller.signal.aborted ||
        (error && error.name === "AbortError")
      ) {
        request.state = "failed";
        setHasError(false);
        setStatus("");
        return;
      }

      request.state = "failed";
      setResults([]);
      setHasError(true);
      setStatus("");
    };

    let promise;

    try {
      promise = searchRef.current(query, { signal: controller.signal });
    } catch (error) {
      rejectRequest(error);
      return;
    }

    Promise.resolve(promise).then(resolveRequest, rejectRequest);
  }

  useEffect(() => {
    mountedRef.current = true;

    return () => {
      mountedRef.current = false;
      clearPendingTimer();

      const request = latestRequestRef.current;
      latestRequestRef.current = null;

      if (
        request?.state === "pending" &&
        !request.controller.signal.aborted
      ) {
        request.controller.abort();
      }
    };
  }, []);

  useEffect(() => {
    const query = value.trim();

    if (query.length < minChars) {
      resetForShortQuery();
      return undefined;
    }

    clearPendingTimer();

    const generation = timerGenerationRef.current + 1;
    timerGenerationRef.current = generation;

    const timerId = setTimeout(() => {
      if (
        timerGenerationRef.current !== generation ||
        timerRef.current !== timerId
      ) {
        return;
      }

      timerRef.current = null;

      if (!mountedRef.current) {
        return;
      }

      const currentQuery = valueRef.current.trim();

      if (
        currentQuery !== query ||
        currentQuery.length < minCharsRef.current
      ) {
        return;
      }

      startRequest(query);
    }, debounceMs);

    timerRef.current = timerId;

    return () => {
      if (timerRef.current === timerId) {
        clearTimeout(timerId);
        timerRef.current = null;
      }

      if (timerGenerationRef.current === generation) {
        timerGenerationRef.current += 1;
      }
    };
  }, [value, editVersion, debounceMs, minChars]);

  function handleChange(event) {
    const nextValue = event.target.value;
    valueRef.current = nextValue;

    setValue(nextValue);
    setEditVersion((version) => version + 1);
    clearPendingTimer();

    if (nextValue.trim().length < minCharsRef.current) {
      resetForShortQuery();
    }
  }

  function handleRetry() {
    const query = valueRef.current.trim();

    if (query.length < minCharsRef.current) {
      resetForShortQuery();
      return;
    }

    startRequest(query);
  }

  return (
    <div>
      <input
        type="search"
        aria-label="Search"
        value={value}
        onChange={handleChange}
      />
      <div role="status">{status}</div>
      {hasError && (
        <div role="alert">
          <span>Something went wrong</span>{" "}
          <button type="button" onClick={handleRetry}>
            Retry
          </button>
        </div>
      )}
      <ul aria-label="Results">
        {results.map((result, index) => (
          <li key={index}>{result}</li>
        ))}
      </ul>
    </div>
  );
}
